function id(variant: InternalFloodPraVariant, code: string): string {
  return `${variant}-${code.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
}

function reference(sr: string): SRReference {
  const entry = INTERNAL_FLOOD_PRA_SR_CATALOG[sr];
  if (entry === undefined) throw new Error(`Unknown Internal Flood requirement ${sr}`);
  return { sr, hlr: entry.hlr };
}

function record(variant: InternalFloodPraVariant, code: string, name: string, description: string, basis: string, evidenceRefs: string[] = []): InternalFloodAnalysisRecord {
  return {
    uuid: id(variant, code), code, name, description, basis, owner: "Internal Flood PRA Team", status: "APPROVED",
    evidenceRefs, relatedRefs: [], assumptionRefs: [], implementsSrs: [],
  };
}

type SourceProfile = Pick<InternalFloodPRA["sourcesIdentificationAndCharacterization"]["sources"][number], "sourceType" | "fluid" | "operatingPressureKpa" | "operatingTemperatureCelsius" | "nominalDiameterMillimetres" | "material"> & { inventoryCubicMetres?: number };

function sourceProfile(system: string): SourceProfile {
  const normalized = system.toLowerCase();
  if (normalized === "steam") return { sourceType: "PIPE", fluid: "STEAM", operatingPressureKpa: 6_500, operatingTemperatureCelsius: 285, nominalDiameterMillimetres: 300, material: "Low-alloy ferritic steel" };
  if (normalized.includes("feedwater")) return { sourceType: "PIPE", fluid: "WATER", operatingPressureKpa: 8_600, operatingTemperatureCelsius: 225, nominalDiameterMillimetres: 250, material: "Carbon steel" };
  if (normalized.includes("fire protection")) return { sourceType: "FIRE_SUPPRESSION", fluid: "WATER", operatingPressureKpa: 1_030, operatingTemperatureCelsius: 21, nominalDiameterMillimetres: 200, material: "Cement-lined carbon steel" };
  if (normalized.includes("service water")) return { sourceType: "PIPE", fluid: "WATER", operatingPressureKpa: 720, operatingTemperatureCelsius: 24, nominalDiameterMillimetres: 250, material: "Duplex stainless steel" };
  if (normalized.includes("closed cooling") || normalized.includes("component cooling")) return { sourceType: "HEAT_EXCHANGER", fluid: "WATER", operatingPressureKpa: 830, operatingTemperatureCelsius: 46, nominalDiameterMillimetres: 150, material: "Austenitic stainless steel" };
  if (normalized.includes("chilled water")) return { sourceType: "PIPE", fluid: "WATER", operatingPressureKpa: 520, operatingTemperatureCelsius: 9, nominalDiameterMillimetres: 100, material: "Carbon steel" };
  if (normalized.includes("condensate")) return { sourceType: "PIPE", fluid: "WATER", operatingPressureKpa: 1_380, operatingTemperatureCelsius: 58, nominalDiameterMillimetres: 250, material: "Carbon steel" };
  if (normalized.includes("pool makeup")) return { sourceType: "POOL", fluid: "WATER", operatingPressureKpa: 450, operatingTemperatureCelsius: 27, nominalDiameterMillimetres: 100, material: "Austenitic stainless steel", inventoryCubicMetres: 680 };
  if (normalized.includes("radwaste")) return { sourceType: "TANK", fluid: "WATER", operatingPressureKpa: 310, operatingTemperatureCelsius: 42, nominalDiameterMillimetres: 80, material: "Austenitic stainless steel", inventoryCubicMetres: 95 };
  if (normalized.includes("temporary maintenance")) return { sourceType: "HOSE", fluid: "WATER", operatingPressureKpa: 550, operatingTemperatureCelsius: 24, nominalDiameterMillimetres: 50, material: "Wire-reinforced elastomer" };
  if (normalized.includes("sodium fire suppression")) return { sourceType: "VESSEL", fluid: "CHEMICAL", operatingPressureKpa: 1_100, operatingTemperatureCelsius: 22, nominalDiameterMillimetres: 65, material: "Stainless steel", inventoryCubicMetres: 18 };
  if (normalized.includes("roof drainage")) return { sourceType: "EXTERNAL_CONNECTION", fluid: "WATER", operatingPressureKpa: 35, operatingTemperatureCelsius: 12, nominalDiameterMillimetres: 200, material: "Coated carbon steel" };
  if (normalized.includes("potable")) return { sourceType: "PIPE", fluid: "WATER", operatingPressureKpa: 410, operatingTemperatureCelsius: 21, nominalDiameterMillimetres: 80, material: "Copper-nickel alloy" };
  if (normalized.includes("demineralized")) return { sourceType: "TANK", fluid: "WATER", operatingPressureKpa: 520, operatingTemperatureCelsius: 24, nominalDiameterMillimetres: 100, material: "Austenitic stainless steel", inventoryCubicMetres: 140 };
  return { sourceType: "PIPE", fluid: "WATER", operatingPressureKpa: 690, operatingTemperatureCelsius: 32, nominalDiameterMillimetres: 150, material: "Carbon steel" };
}

function cover(records: InternalFloodAnalysisRecord[], prefix: InternalFloodPraSubelement): void {
  const requirements = Object.keys(INTERNAL_FLOOD_PRA_SR_CATALOG).filter((sr) => sr.startsWith(`${prefix}-`));
  requirements.forEach((sr, index) => records[index % records.length]?.implementsSrs.push(reference(sr)));
}

function documentation(variant: InternalFloodPraVariant, prefix: InternalFloodPraSubelement, name: string, process: string, inputs: string, methods: string, results: string): InternalFloodProcessDocumentation {
  const requirements = Object.keys(INTERNAL_FLOOD_PRA_SR_CATALOG).filter((sr) => sr.startsWith(`${prefix}-`));
  return {
    uuid: id(variant, `DOC-${prefix}`), name, processDescription: process, inputsDescription: inputs, methodsDescription: methods, resultsDescription: results,
    limitations: ["Pre-operational spatial and configuration assumptions remain controlled until turnover walkdowns close them.", "Lower-risk screened areas use conservative bounding representations."],
    supportingDocumentRefs: [id(variant, "EVID-GA"), id(variant, "EVID-PID"), id(variant, "EVID-WALK")],
    traceabilityLinks: requirements.map((sr) => ({
      uuid: id(variant, `TRACE-${sr}`), requirementRef: sr, inputRefs: [id(variant, "EVID-GA")], modelRefs: [id(variant, `${prefix}-MODEL`)],
      resultRefs: [id(variant, `${prefix}-RESULT`)], documentationRefs: [id(variant, `DOC-${prefix}`)],
    })),
  };
}

